Services::Services(Window *parent) : QObject(parent), window(parent), network(this) {}
bool Services::validateTheme(const QJsonObject &object, QString *error) {
    auto fail = [&] { if (error) *error = "主题需要有效名称、六位十六进制颜色和 0–30 范围行距。"; return false; };
    if (object.value("name").toString().isEmpty() || object.value("name").toString().size() > 100 || object.value("fontName").toString().size() > 200) return fail();
    for (auto key : {"background", "foreground", "accent", "codeBackground"}) if (!QRegularExpression("^#?[0-9a-fA-F]{6}$").match(object.value(key).toString()).hasMatch()) return fail();
    double spacing = object.value("lineSpacing").toDouble(-1); if (!std::isfinite(spacing) || spacing < 0 || spacing > 30) return fail(); return true;
}
void Services::applyTheme() {
    QSettings settings; QString name = settings.value("theme", "system").toString(); QPalette palette = QApplication::style()->standardPalette();
    QJsonObject object;
    if (name == "custom") object = QJsonDocument::fromJson(settings.value("customTheme").toByteArray()).object();
    else if (name == "dark") object = {{"background","242832"},{"foreground","E2E5ED"},{"accent","91A6ED"},{"codeBackground","303641"}};
    else if (name == "sepia") object = {{"background","FAF7EF"},{"foreground","292D34"},{"accent","5968B2"},{"codeBackground","EEEAE1"}};
    else if (name == "solarized") object = {{"background","FDF6E3"},{"foreground","657B83"},{"accent","268BD2"},{"codeBackground","EEE8D5"}};
    else if (name == "light") object = {{"background","FFFFFF"},{"foreground","20242C"},{"accent","5968B2"},{"codeBackground","F0F2F6"}};
    auto color = [&](const QString &key) { auto raw = object.value(key).toString(); return QColor(raw.startsWith('#') ? raw : "#" + raw); };
    if (!object.isEmpty()) { palette.setColor(QPalette::Base,color("background")); palette.setColor(QPalette::Window,color("background")); palette.setColor(QPalette::Text,color("foreground")); palette.setColor(QPalette::WindowText,color("foreground")); palette.setColor(QPalette::ButtonText,color("foreground")); palette.setColor(QPalette::Button,color("codeBackground")); palette.setColor(QPalette::Highlight,color("accent"));palette.setColor(QPalette::Link,color("accent")); palette.setColor(QPalette::HighlightedText,Qt::white); palette.setColor(QPalette::AlternateBase,color("codeBackground")); }
    qApp->setPalette(palette);
    QFont font(object.value("fontName").toString().isEmpty() ? "sans-serif" : object.value("fontName").toString(),std::clamp(settings.value("fontSize",13).toInt(),6,96));
    for (auto w : Window::windows) if (w) { w->editor->setFont(font);w->editor->updateGutter(); QFont metrics(font);metrics.setPointSizeF(font.pointSizeF()+settings.value("lineSpacing",4).toDouble()*.35);w->editor->document()->setDefaultFont(metrics);w->preview->setFont(font); w->refreshPreview(); w->editor->highlighter->rehighlight(); }
}
void Services::importTheme() {
    QString path=QFileDialog::getOpenFileName(window,"导入 JSON 主题",{},"JSON (*.json)");if(path.isEmpty())return;QFile file(path);if(!file.open(QIODevice::ReadOnly)||file.size()>100000){QMessageBox::warning(window,"导入失败","无法读取主题或文件过大。");return;}auto object=QJsonDocument::fromJson(file.readAll()).object();QString error;if(!validateTheme(object,&error)){QMessageBox::warning(window,"主题无效",error);return;}QSettings().setValue("customTheme",QJsonDocument(object).toJson());QSettings().setValue("theme","custom");QSettings().setValue("lineSpacing",object.value("lineSpacing").toDouble());applyTheme();
}
void Services::exportTheme() {
    QString path=QFileDialog::getSaveFileName(window,"导出主题模板","Mojian-Theme.json","JSON (*.json)");if(path.isEmpty())return;auto object=QJsonDocument::fromJson(QSettings().value("customTheme").toByteArray()).object();if(object.isEmpty())object={{"name","My Theme"},{"background","FAF7EF"},{"foreground","292D34"},{"accent","5968B2"},{"codeBackground","EEEAE1"},{"fontName",""},{"lineSpacing",6},{"dark",false}};QSaveFile file(path);if(file.open(QIODevice::WriteOnly)){file.write(QJsonDocument(object).toJson());if(!file.commit())QMessageBox::warning(window,"导出失败",file.errorString());}
}
QString Services::credential(bool save,const QString &token) {
    QString executable=QStandardPaths::findExecutable("secret-tool");if(executable.isEmpty())return {};
    QProcess process;QStringList args=save?QStringList{"store","--label=Mojian image upload","service","io.mojian.Editor","account","image-upload"}:QStringList{"lookup","service","io.mojian.Editor","account","image-upload"};process.start(executable,args);
    if(!process.waitForStarted(1000))return {};if(save){process.write(token.toUtf8());process.closeWriteChannel();}if(!process.waitForFinished(10000)){process.kill();process.waitForFinished(500);return {};}if(process.exitCode()!=0)return {};return save?QStringLiteral("OK"):QString::fromUtf8(process.readAllStandardOutput()).trimmed();
}
QUrl Services::uploadUrl(const QString &text) {
    QUrl url(text);bool loopback=QStringList{"localhost","127.0.0.1","::1"}.contains(url.host());if(!url.isValid()||url.host().isEmpty()||!url.userInfo().isEmpty()||!(url.scheme()=="https"||(url.scheme()=="http"&&loopback)))return {};return url;
}
QString Services::responseUrl(const QByteArray &data,const QString &path) {
    QJsonParseError error;auto document=QJsonDocument::fromJson(data,&error);if(error.error!=QJsonParseError::NoError)return {};QJsonValue value(document.object());for(const auto &part:path.split('.',Qt::SkipEmptyParts)){if(value.isArray()){bool ok;int index=part.toInt(&ok);if(!ok)return {};value=index>=0&&index<value.toArray().size()?value.toArray().at(index):QJsonValue();}else value=value.toObject().value(part);}auto text=value.toString();QUrl url(text);return url.isValid()&&!url.host().isEmpty()&&QStringList{"http","https"}.contains(url.scheme())?text:QString();
}
void Services::uploadImage() {
    if(upload)return;QSettings settings;auto url=uploadUrl(settings.value("uploadEndpoint").toString());if(url.isEmpty()){QMessageBox::information(window,"上传设置","请先在设置中配置兼容的 HTTPS multipart 上传服务。");return;}auto file=QFileDialog::getOpenFileName(window,"上传图片",{},"图片 (*.png *.jpg *.jpeg *.gif *.webp)");if(file.isEmpty())return;QFile input(file);if(!input.open(QIODevice::ReadOnly)||input.size()>25000000){QMessageBox::warning(window,"上传失败","无法读取图片或图片超过 25 MB。");return;}
    QPointer<Editor> target=window->focusedEditor();QString original=window->editor->toPlainText(),targetOriginal=target->toPlainText();auto cursor=target->textCursor();auto multipart=new QHttpMultiPart(QHttpMultiPart::FormDataType);QHttpPart part;QString filename=QFileInfo(file).fileName();filename.remove('"').remove('\r').remove('\n');QString field=settings.value("uploadField","file").toString();if(field.contains(QRegularExpression("[\"\\r\\n]"))||field.isEmpty()){delete multipart;QMessageBox::warning(window,"上传失败","表单字段无效。");return;}part.setHeader(QNetworkRequest::ContentDispositionHeader,"form-data; name=\""+field+"\"; filename=\""+filename+"\"");QMimeDatabase db;part.setHeader(QNetworkRequest::ContentTypeHeader,db.mimeTypeForFile(file).name());part.setBody(input.readAll());multipart->append(part);
    QNetworkRequest request(url);request.setTransferTimeout(30000);request.setAttribute(QNetworkRequest::RedirectPolicyAttribute,QNetworkRequest::ManualRedirectPolicy);QString token=tokenProvider?tokenProvider():credential(),prefix=settings.value("uploadAuthPrefix","Bearer").toString();if(token.contains('\r')||token.contains('\n')||prefix.contains('\r')||prefix.contains('\n')){delete multipart;return;}if(!token.isEmpty())request.setRawHeader("Authorization",((prefix.isEmpty()?QString():prefix+" ")+token).toUtf8());auto reply=network.post(request,multipart);multipart->setParent(reply);upload=reply;
    auto progress=new QProgressDialog("正在上传图片……","取消",0,100,window);progress->setMinimumDuration(0);connect(progress,&QProgressDialog::canceled,reply,&QNetworkReply::abort);connect(reply,&QNetworkReply::uploadProgress,progress,[progress](qint64 sent,qint64 total){if(total>0)progress->setValue(sent*100/total);});
    connect(reply,&QNetworkReply::finished,this,[this,reply,progress,original,target,targetOriginal,cursor]()mutable{progress->close();progress->deleteLater();upload=nullptr;if(reply->error()==QNetworkReply::OperationCanceledError){reply->deleteLater();return;}auto result=responseUrl(reply->readAll(),QSettings().value("uploadResultPath","data.url").toString());int status=reply->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt();if(reply->error()!=QNetworkReply::NoError||status<200||status>=300||result.isEmpty())QMessageBox::warning(window,"上传失败","请检查服务地址、认证、表单字段及 JSON 返回路径。\n"+reply->errorString());else if(!target||window->editor->toPlainText()!=original||target->toPlainText()!=targetOriginal)QMessageBox::information(window,"上传完成","文档已变化，未自动插入。图片地址：\n"+result);else{cursor.insertText("![图片]("+result+")");target->setTextCursor(cursor);}reply->deleteLater();});
}
QString Services::pandocExecutable(){auto path=QStandardPaths::findExecutable("pandoc");if(!path.isEmpty())return path;for(auto candidate:QStringList{QDir::homePath()+"/.local/lib/mojian/bin/pandoc",QCoreApplication::applicationDirPath()+"/../tools/bin/pandoc"})if(QFileInfo(candidate).isExecutable())return QFileInfo(candidate).absoluteFilePath();return {};}
QString Services::portableHtml(QTextDocument *document){QString html=document->toHtml();auto matches=QRegularExpression("src=\"(mojian-generated:[^\"]+)\"").globalMatch(html);QList<QPair<QString,QString>> replacements;while(matches.hasNext()){auto match=matches.next();auto resource=document->resource(QTextDocument::ImageResource,QUrl(match.captured(1)));QImage image=qvariant_cast<QImage>(resource);if(image.isNull())continue;QByteArray data;QBuffer buffer(&data);buffer.open(QIODevice::WriteOnly);image.save(&buffer,"PNG");replacements<<qMakePair(match.captured(1),"data:image/png;base64,"+QString::fromLatin1(data.toBase64()));}for(auto pair:replacements)html.replace(pair.first,pair.second);return html;}
void Services::convert(const QString &input,const QString &destination,const QString &format,bool importing,QSharedPointer<QTemporaryDir> temporary) {
    QString executable=pandocExecutable();if(executable.isEmpty()){QMessageBox::information(window,"需要 Pandoc","请安装 Pandoc 后使用此格式。原生 PDF、RTF、HTML 和纯文本导出无需 Pandoc。");return;}if(!temporary)temporary=QSharedPointer<QTemporaryDir>::create();QString stage=temporary->filePath("output."+(format=="latex"?"tex":format));auto process=new QProcess(this);QStringList args{input,"--standalone","--to="+format,"--output="+stage,"--resource-path="+(window->filePath.isEmpty()?QFileInfo(input).absolutePath():QFileInfo(window->filePath).absolutePath())};if(!importing)args<<"--from=markdown";
    auto progress=new QProgressDialog("正在转换文档……","取消",0,0,window);progress->setMinimumDuration(0);connect(progress,&QProgressDialog::canceled,process,&QProcess::kill);connect(process,qOverload<int,QProcess::ExitStatus>(&QProcess::finished),this,[=](int code,QProcess::ExitStatus status){bool cancelled=progress->wasCanceled();progress->close();progress->deleteLater();if(!cancelled){QFile file(stage);if(code==0&&status==QProcess::NormalExit&&file.open(QIODevice::ReadOnly)){QSaveFile output(destination);auto data=file.readAll();if(output.open(QIODevice::WriteOnly)&&output.write(data)==data.size()&&output.commit()){if(importing)(new Window(destination))->show();}else QMessageBox::warning(window,"转换失败",output.errorString());}else QMessageBox::warning(window,"转换失败",QString::fromUtf8(process->readAllStandardError()).left(5000));}process->deleteLater();});connect(process,&QProcess::errorOccurred,this,[=](QProcess::ProcessError error){if(error==QProcess::FailedToStart){progress->close();progress->deleteLater();QMessageBox::warning(window,"转换失败",process->errorString());process->deleteLater();}});process->start(executable,args);
}
void Services::exportFormat(const QString &format) {
    QString extension=format=="latex"?"tex":format;QString path=QFileDialog::getSaveFileName(window,"导出 "+format.toUpper(),(window->filePath.isEmpty()?"未命名":QFileInfo(window->filePath).completeBaseName())+"."+extension,format.toUpper()+" (*."+extension+")");if(path.isEmpty())return;
    if(format=="rtf"){window->refreshPreview();ImageDocument document;document.setDefaultFont(QFont("sans-serif",12));Markdown::render(&document,window->editor->toPlainText(),window->preview->document()->baseUrl(),470,QSettings().value("dialect","extended").toString(),true);QSaveFile file(path);auto data=rtf(&document).toLatin1();if(!file.open(QIODevice::WriteOnly)||file.write(data)!=data.size()||!file.commit())QMessageBox::warning(window,"导出失败",file.errorString());return;}
    auto temporary=QSharedPointer<QTemporaryDir>::create();QString input=temporary->filePath("source.md");QFile file(input);if(!file.open(QIODevice::WriteOnly)){QMessageBox::warning(window,"导出失败",file.errorString());return;}file.write(window->editor->toPlainText().toUtf8());file.close();convert(input,path,format,false,temporary);
}
void Services::importDocument() {QString input=QFileDialog::getOpenFileName(window,"导入 Word / RTF / EPUB",{},"文档 (*.docx *.rtf *.epub *.odt)");if(input.isEmpty())return;QString output=QFileDialog::getSaveFileName(window,"保存 Markdown",QFileInfo(input).completeBaseName()+".md","Markdown (*.md)");if(!output.isEmpty())convert(input,output,"gfm",true);}
QString Services::rtf(QTextDocument *document) {
    auto escape=[](const QString &text){QString result;for(QChar ch:text){ushort c=ch.unicode();if(c=='\\'||c=='{'||c=='}')result+='\\'+QString(ch);else if(c=='\n'||c==QChar::LineSeparator)result+="\\line ";else if(c>127)result+="\\u"+QString::number(qint16(c))+"?";else result+=ch;}return result;};
    auto fragmentText=[&](QTextFragment fragment,int start,int end){auto format=fragment.charFormat();QString text=fragment.text().mid(std::max(start-fragment.position(),0),std::max(0,std::min(fragment.position()+fragment.length(),end)-std::max(start,fragment.position())));QString result="{";if(format.fontWeight()>=QFont::Bold)result+="\\b ";if(format.fontItalic())result+="\\i ";if(format.fontUnderline())result+="\\ul ";if(format.fontStrikeOut())result+="\\strike ";if(format.verticalAlignment()==QTextCharFormat::AlignSuperScript)result+="\\super ";if(format.verticalAlignment()==QTextCharFormat::AlignSubScript)result+="\\sub ";if(format.fontPointSize()>0)result+="\\fs"+QString::number(qRound(format.fontPointSize()*2))+" ";
        if(format.isImageFormat()){auto imageFormat=format.toImageFormat();QImage image=qvariant_cast<QImage>(document->resource(QTextDocument::ImageResource,QUrl(imageFormat.name())));if(!image.isNull()){QByteArray data;QBuffer buffer(&data);buffer.open(QIODevice::WriteOnly);image.save(&buffer,"PNG");result+="{\\pict\\pngblip\\picw"+QString::number(image.width())+"\\pich"+QString::number(image.height())+"\\picwgoal"+QString::number(qRound((imageFormat.width()>0?imageFormat.width():image.width())*15))+"\\pichgoal"+QString::number(qRound((imageFormat.height()>0?imageFormat.height():image.height())*15))+"\n"+QString::fromLatin1(data.toHex())+"}";}else result+=escape(text);}
        else result+=escape(text);result+="}";if(format.isAnchor()&&!format.anchorHref().isEmpty()&&!format.anchorHref().startsWith('#')){QString href=QString::fromLatin1(QUrl(format.anchorHref()).toEncoded(QUrl::FullyEncoded));result="{\\field{\\*\\fldinst HYPERLINK \""+escape(href)+"\"}{\\fldrslt "+result+"}}";}return result;};
    auto range=[&](int start,int end){QString result;for(auto block=document->findBlock(start);block.isValid()&&block.position()<end;block=block.next()){for(auto it=block.begin();!it.atEnd();++it){auto fragment=it.fragment();if(fragment.isValid()&&fragment.position()<end&&fragment.position()+fragment.length()>start)result+=fragmentText(fragment,start,end);}if(block.next().isValid()&&block.next().position()<end)result+="\\line ";}return result;};
    QString output="{\\rtf1\\ansi\\deff0{\\fonttbl{\\f0 sans-serif;}}\\uc1\n";QSet<QTextTable *> written;
    for(auto block=document->begin();block.isValid();block=block.next()){QTextCursor cursor(block);auto table=cursor.currentTable();if(table){if(written.contains(table))continue;written.insert(table);int columns=table->columns(),width=std::max(300,8640/std::max(1,columns));for(int r=0;r<table->rows();++r){output+="\\trowd\\trgaph80 ";if(r==0)output+="\\trhdr ";for(int c=0;c<columns;++c){auto cell=table->cellAt(r,c);if(cell.columnSpan()>1)output+=cell.column()==c?"\\clmgf ":"\\clmrg ";if(cell.rowSpan()>1)output+=cell.row()==r?"\\clvmgf ":"\\clvmrg ";output+="\\cellx"+QString::number((c+1)*width)+" ";}for(int c=0;c<columns;++c){auto cell=table->cellAt(r,c);output+="\\pard\\intbl ";if(cell.row()==r&&cell.column()==c)output+=range(cell.firstPosition(),cell.lastPosition());output+="\\cell ";}output+="\\row\n";}continue;}
        output+="\\pard ";auto format=block.blockFormat();if(format.alignment()&Qt::AlignHCenter)output+="\\qc ";else if(format.alignment()&Qt::AlignRight)output+="\\qr ";output+=range(block.position(),block.position()+block.length()-1)+"\\par\n";
    }return output+"}";
}
void Services::inspectImage() {
    auto editor=window->focusedEditor();QString source=editor->toPlainText();auto cursor=editor->textCursor();auto snapshot=Markdown::parse(source,QSettings().value("dialect","extended").toString());MdNode selected;bool found=false;for(auto node:Markdown::descendants(snapshot->root))if(node.type=="image"&&cursor.position()>=node.start&&cursor.position()<=node.end){selected=node;found=true;break;}if(!found){QMessageBox::information(window,"图片设置","请先把光标放在图片标记内。");return;}QString description;for(auto node:Markdown::descendants(selected))if(node.type=="text"||node.type=="code")description+=node.literal;auto metadata=QRegularExpression("^\\{width=(\\d+)\\}").match(source.mid(selected.end));int end=selected.end+(metadata.hasMatch()?metadata.capturedLength():0);
    QDialog dialog(window);dialog.setWindowTitle("图片设置");QFormLayout layout(&dialog);QLineEdit path(selected.url),alt(description);QSpinBox width;width.setRange(0,12000);width.setSpecialValueText("原始宽度");width.setValue(metadata.captured(1).toInt());layout.addRow("路径或 URL",&path);layout.addRow("替代文字",&alt);layout.addRow("宽度（像素）",&width);QDialogButtonBox buttons(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);layout.addRow(&buttons);connect(&buttons,&QDialogButtonBox::accepted,&dialog,&QDialog::accept);connect(&buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);if(dialog.exec()==QDialog::Accepted){QString label=alt.text();label.replace('\\',"\\\\").replace('[',"\\[").replace(']',"\\]");QString url=QString::fromLatin1(QUrl::toPercentEncoding(path.text(),":/?#[]@!$&'*,;=+-._~%"));cursor.setPosition(selected.start);cursor.setPosition(end,QTextCursor::KeepAnchor);cursor.insertText("!["+label+"]("+url+")"+(width.value()?"{width="+QString::number(width.value())+"}":QString()));}
}
